CREATE TABLE "ParentStudent"("parentId" TEXT NOT NULL,"studentId" TEXT NOT NULL,"relationship" TEXT NOT NULL DEFAULT 'PARENT',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ParentStudent_pkey" PRIMARY KEY("parentId","studentId"));
CREATE TABLE "Announcement"("id" TEXT NOT NULL,"title" TEXT NOT NULL,"body" TEXT NOT NULL,"branchId" TEXT,"audience" "Role","authorId" TEXT NOT NULL,"isArchived" BOOLEAN NOT NULL DEFAULT false,"publishedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Announcement_pkey" PRIMARY KEY("id"));
CREATE TABLE "PortalMessage"("id" TEXT NOT NULL,"senderId" TEXT NOT NULL,"recipientId" TEXT NOT NULL,"subject" TEXT NOT NULL,"body" TEXT NOT NULL,"readAt" TIMESTAMP(3),"senderArchived" BOOLEAN NOT NULL DEFAULT false,"recipientArchived" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PortalMessage_pkey" PRIMARY KEY("id"));
CREATE TABLE "LeaveRequest"("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"branchId" TEXT NOT NULL,"fromDate" DATE NOT NULL,"toDate" DATE NOT NULL,"reason" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"remarks" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "LeaveRequest_pkey" PRIMARY KEY("id"));
CREATE INDEX "ParentStudent_studentId_idx" ON "ParentStudent"("studentId");CREATE INDEX "Announcement_branchId_audience_publishedAt_idx" ON "Announcement"("branchId","audience","publishedAt");CREATE INDEX "PortalMessage_senderId_createdAt_idx" ON "PortalMessage"("senderId","createdAt");CREATE INDEX "PortalMessage_recipientId_createdAt_idx" ON "PortalMessage"("recipientId","createdAt");CREATE UNIQUE INDEX "LeaveRequest_userId_fromDate_toDate_key" ON "LeaveRequest"("userId","fromDate","toDate");CREATE INDEX "LeaveRequest_branchId_status_idx" ON "LeaveRequest"("branchId","status");
ALTER TABLE "ParentStudent" ADD CONSTRAINT "ParentStudent_parentId_fkey" FOREIGN KEY("parentId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "ParentStudent" ADD CONSTRAINT "ParentStudent_studentId_fkey" FOREIGN KEY("studentId") REFERENCES "StudentProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "Announcement" ADD CONSTRAINT "Announcement_branchId_fkey" FOREIGN KEY("branchId") REFERENCES "Branch"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "Announcement" ADD CONSTRAINT "Announcement_authorId_fkey" FOREIGN KEY("authorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "PortalMessage" ADD CONSTRAINT "PortalMessage_senderId_fkey" FOREIGN KEY("senderId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "PortalMessage" ADD CONSTRAINT "PortalMessage_recipientId_fkey" FOREIGN KEY("recipientId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "LeaveRequest" ADD CONSTRAINT "LeaveRequest_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "LeaveRequest" ADD CONSTRAINT "LeaveRequest_branchId_fkey" FOREIGN KEY("branchId") REFERENCES "Branch"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
